// Get all items from input
const items = $input.all();

// Use first item for order-level details
const firstItem = items[0].json;

// Determine dispatch type
const isCollection = firstItem.dispatchMethod === 'Collection';

// Build items HTML
let itemsHtml = '';
for (const item of items) {
  const data = item.json;

  itemsHtml += `
    <tr>
      <td style="padding: 15px 0; border-bottom: 1px solid #eeeeee;">
        <table width="100%" cellpadding="0" cellspacing="0">
          <tr>
            <td style="vertical-align: top;">
              <h3 style="margin: 0 0 5px 0; color: #333333; font-size: 16px; font-weight: bold;">${data.deviceType}</h3>
              <p style="margin: 0 0 8px 0; color: #666666; font-size: 13px;">Item Code: ${data.itemCode}</p>
              <div style="margin-top: 8px;">
                <span style="display: inline-block; background-color: #e8f5e9; color: #2e7d32; padding: 4px 10px; border-radius: 4px; font-size: 12px; font-weight: 600; margin-right: 8px;">
                  ${data.pickStatus}
                </span>
                <span style="display: inline-block; background-color: #f0e6f9; color: #7209B7; padding: 4px 10px; border-radius: 4px; font-size: 12px; font-weight: 600;">
                  Qty: ${data.quantityOrdered}
                </span>
              </div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  `;
}

// Build conditional sections
const technicianRow = firstItem.technician ? `
  <tr>
    <td style="color: #666666; font-size: 14px; padding: 8px 0;">Technician:</td>
    <td style="color: #333333; font-size: 14px; font-weight: bold; text-align: right; padding: 8px 0;">${firstItem.technician}</td>
  </tr>
` : '';

const companyRow = firstItem.recipientCompanyName ? `
  <tr>
    <td style="color: #666666; font-size: 14px; padding: 8px 0;">Company:</td>
    <td style="color: #333333; font-size: 14px; font-weight: bold; text-align: right; padding: 8px 0;">${firstItem.recipientCompanyName}</td>
  </tr>
` : '';

const cellPhoneRow = firstItem.cellPhoneNumber ? `
  <tr>
    <td style="color: #666666; font-size: 14px; padding: 8px 0;">Mobile:</td>
    <td style="color: #333333; font-size: 14px; font-weight: bold; text-align: right; padding: 8px 0;">${firstItem.cellPhoneNumber}</td>
  </tr>
` : '';

const waybillSection = firstItem.waybillNumber ? `
  <p style="margin: 8px 0 0 0; color: ${isCollection ? '#1565c0' : '#e65100'}; font-size: 14px; font-weight: bold;">
    Waybill Number: ${firstItem.waybillNumber}
  </p>
` : '';

const additionalNotes = firstItem.additionalNotes ? `
  <table width="100%" cellpadding="0" cellspacing="0" style="background-color: #fffbf0; border-left: 4px solid #ff9800; border-radius: 4px; margin: 25px 0;">
    <tr>
      <td style="padding: 20px;">
        <h3 style="margin: 0 0 10px 0; color: #e65100; font-size: 16px; font-weight: bold;">📝 Additional Notes</h3>
        <p style="margin: 0; color: #555555; font-size: 14px; line-height: 1.6;">
          ${firstItem.additionalNotes}
        </p>
      </td>
    </tr>
  </table>
` : '';

// Alert config
const alertBgColor = isCollection ? '#e3f2fd' : '#fff3e0';
const alertBorderColor = isCollection ? '#1976d2' : '#f57c00';
const alertTextColor = isCollection ? '#1565c0' : '#e65100';
const alertIcon = isCollection ? '📍' : '🚚';
const alertTitle = isCollection ? 'Collection Required' : 'Courier Dispatch';
const alertMessage = isCollection 
  ? `Please collect your order from: ${firstItem.warehouseFulfilling}`
  : `Your order will be dispatched via ${firstItem.deliveryParty}`;

// Next steps
const headerTitle = isCollection ? '📦 Order Ready for Collection' : '🚚 Order Ready for Dispatch';
const dispatchType = isCollection ? 'collection' : 'dispatch';
const nextStepsTitle = isCollection ? '📍 Next Steps - Collection' : '📦 Next Steps - Delivery';
const nextStepsList = isCollection ? `
  <li>Your order is ready for collection at ${firstItem.warehouseFulfilling}</li>
  <li>Please bring valid identification when collecting</li>
  <li>Contact us if you need to arrange a different collection time</li>
` : `
  <li>Your order will be dispatched via ${firstItem.deliveryParty}</li>
  ${firstItem.waybillNumber ? `<li>Track your shipment using waybill number: ${firstItem.waybillNumber}</li>` : ''}
  <li>You'll receive a delivery notification once the courier is on the way</li>
  <li>Please ensure someone is available to receive the delivery</li>
`;

// Return prepared data for HTML template
return [{
  json: {
    headerTitle: headerTitle,
    recipientName: firstItem.recipientName,
    orderId: firstItem.orderId,
    dispatchType: dispatchType,
    alertBgColor: alertBgColor,
    alertBorderColor: alertBorderColor,
    alertTextColor: alertTextColor,
    alertIcon: alertIcon,
    alertTitle: alertTitle,
    alertMessage: alertMessage,
    waybillSection: waybillSection,
    dateOrdered: firstItem.dateOrdered,
    totalItems: firstItem.totalItems,
    totalQuantity: firstItem.totalQuantity,
    orderedBy: firstItem.orderedBy,
    technicianRow: technicianRow,
    warehouseFulfilling: firstItem.warehouseFulfilling,
    region: firstItem.region,
    companyRow: companyRow,
    recipientAddress: firstItem.recipientAddress,
    recipientContactNumber: firstItem.recipientContactNumber,
    cellPhoneRow: cellPhoneRow,
    recipientEmail: firstItem.recipientEmail,
    itemsHtml: itemsHtml,
    additionalNotes: additionalNotes,
    nextStepsTitle: nextStepsTitle,
    nextStepsList: nextStepsList
  }
}];

// Original orderId, e.g. "ORD-0013"
const orderId = $input.first().json.orderedBy;
return [
  {
 orderId
  }
];
